    const pid = await pacienteIdDe(app, 'ana@email.com');
    const criar = await request(app)
      .post('/api/consultas')
      .set('Authorization', `Bearer ${tok}`)
      .send({ pacienteId: pid, medicoId: mid, inicio: '2026-10-20 10:00' });
